package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.UiDevice;
import org.junit.Test;
import java.io.File;
import java.time.ZoneId;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

/** Real settings/save/reopen with private preferences and fake provider/application. */
public final class CalendarRulesFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice device=UiDevice.getInstance(i);CalendarRulesActivity activity;
    void await(java.util.function.BooleanSupplier yes)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!yes.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue("Calendar state ready",yes.getAsBoolean());}
    View find(View root,String text){if(root instanceof Switch&&text.contentEquals(root.getContentDescription()))return root;if(root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View value=find(group.getChildAt(n),text);if(value!=null)return value;}return null;}
    View toggle(View root,String text){if(root instanceof Switch&&text.contentEquals(root.getContentDescription()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View value=toggle(group.getChildAt(n),text);if(value!=null)return value;}return null;}
    boolean shown(String text){boolean[] ready={false};i.runOnMainSync(()->ready[0]=activity!=null&&activity.hasWindowFocus()&&find(activity.getWindow().getDecorView(),text)!=null);return ready[0];}
    void launch()throws Exception{launch("Earlier for meetings");}
    void launch(String expected)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(CalendarRulesActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,CalendarRulesActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Private calendar fixture · no alarms").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(CalendarRulesActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown(expected));}
    void click(String text)throws Exception{await(()->shown(text));Rect[] bounds={null};i.runOnMainSync(()->{View root=activity.getWindow().getDecorView(),view=toggle(root,text);if(view==null)view=find(root,text);assertTrue(view.isEnabled());while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();assertTrue(view.isClickable());view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true);Rect r=new Rect();assertTrue(view.getGlobalVisibleRect(r));assertEquals(view.getHeight(),r.height());bounds[0]=r;});assertTrue(device.click(bounds[0].centerX(),bounds[0].centerY()));}
    View focusedWindow(){View result=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow())result=root;return result;}
    void frame()throws Exception{CountDownLatch committed=new CountDownLatch(1);View[] owner={null};i.runOnMainSync(()->{owner[0]=activity.getWindow().getDecorView();assertSame("Exact focused Calendar window",owner[0],focusedWindow());assertTrue(owner[0].isHardwareAccelerated());owner[0].getViewTreeObserver().registerFrameCommitCallback(committed::countDown);owner[0].invalidate();});assertTrue("Rendered owned Calendar frame",committed.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame("Frame retains exact focused window",owner[0],focusedWindow()));}
    void capture(String name)throws Exception{await(()->shown("Save calendar rules"));i.waitForIdleSync();frame();File dir=new File(c.getExternalFilesDir(null),"verification");assertTrue(dir.isDirectory()||dir.mkdirs());assertTrue(device.takeScreenshot(new File(dir,"calendar-rules-"+name+".png")));}
    void close()throws Exception{CalendarRulesActivity old=activity;i.runOnMainSync(old::finish);await(old::isDestroyed);assertTrue(old.awaitWorkers(8000));}
    void permissionResult(int... result){i.runOnMainSync(()->activity.onRequestPermissionsResult(813,new String[]{android.Manifest.permission.READ_CALENDAR},result));}
    void resumeWith(Runnable change){i.runOnMainSync(()->{i.callActivityOnPause(activity);change.run();i.callActivityOnResume(activity);});}
    @Test public void permissionDenialSettingsReturnAndRevocationKeepTheUnsavedDraft()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());String name="calendar-permission-ui-"+UUID.randomUUID();SharedPreferences privatePrefs=c.getSharedPreferences(name,0);java.util.function.Function<Context,SharedPreferences> oldPrefs=CalendarSettings.factory;CalendarAccess.Factory oldAccess=CalendarAccess.factory;CalendarSync.Port oldApply=CalendarSync.port;CalendarRulesActivity.PermissionActions oldPermissions=CalendarRulesActivity.permissions;AtomicInteger requests=new AtomicInteger(),settings=new AtomicInteger(),reads=new AtomicInteger(),applied=new AtomicInteger();java.util.concurrent.atomic.AtomicBoolean allowed=new java.util.concurrent.atomic.AtomicBoolean(),rationale=new java.util.concurrent.atomic.AtomicBoolean(),fail=new java.util.concurrent.atomic.AtomicBoolean(true);
        try{
            CalendarSettings.factory=context->privatePrefs;CalendarAccess.factory=context->new CalendarAccess.Port(){public boolean allowed(){return allowed.get();}public List<CalendarAccess.Source> sources(CancellationSignal signal){assertTrue(allowed.get());assertNotEquals(Looper.getMainLooper(),Looper.myLooper());reads.incrementAndGet();return List.of(new CalendarAccess.Source(7,"Private calendar"));}public CalendarPolicy.Snapshot snapshot(CalendarPolicy.Rules rules,long now,ZoneId zone,CancellationSignal cancel){throw new AssertionError("No real calendar events");}};CalendarSync.port=context->applied.incrementAndGet();
            CalendarRulesActivity.permissions=new CalendarRulesActivity.PermissionActions(){public boolean rationale(Activity a){return rationale.get();}public void request(Activity a){requests.incrementAndGet();if(fail.getAndSet(false))throw new IllegalStateException("Fixture request unavailable");}public void settings(Activity a){settings.incrementAndGet();}};
            launch("Allow calendar access");click("Use calendar rules");click("Allow calendar access");await(()->shown("Calendar access could not be requested. Try again or open Android Settings."));assertFalse(privatePrefs.getBoolean("readCalendarRequested",false));assertEquals(0,reads.get());
            click("Allow calendar access");await(()->shown("Waiting for Android…"));i.runOnMainSync(()->assertFalse(find(activity.getWindow().getDecorView(),"Waiting for Android…").isEnabled()));permissionResult();await(()->shown("Allow calendar access"));assertFalse(privatePrefs.getBoolean("readCalendarRequested",false));
            click("Allow calendar access");rationale.set(true);permissionResult(android.content.pm.PackageManager.PERMISSION_DENIED);click("Allow calendar access");await(()->shown("Continue to calendar access"));int prompted=requests.get();click("Not now");assertEquals(prompted,requests.get());click("Allow calendar access");click("Continue to calendar access");assertEquals(prompted+1,requests.get());rationale.set(false);permissionResult(android.content.pm.PackageManager.PERMISSION_DENIED);await(()->shown("Open app permission settings"));capture("permission-settings");click("Open app permission settings");assertEquals(1,settings.get());assertEquals(prompted+1,requests.get());
            resumeWith(()->allowed.set(true));await(()->shown("Earlier for meetings"));click("Skip all-day dates");click("Earlier for meetings");capture("permission-granted-draft");int loaded=reads.get();resumeWith(()->allowed.set(false));await(()->shown("Open app permission settings"));assertEquals(loaded,reads.get());Bundle state=new Bundle();i.runOnMainSync(()->i.callActivityOnSaveInstanceState(activity,state));CalendarPolicy.Rules unsaved=CalendarSettings.decode(state.getString("draft"));assertTrue(unsaved.enabled);assertEquals(Set.of(7L),unsaved.holidays);assertEquals(Set.of(7L),unsaved.meetings);assertFalse(privatePrefs.contains("rules"));assertEquals(0,applied.get());capture("permission-revoked-draft");
            resumeWith(()->allowed.set(true));await(()->shown("Earlier for meetings"));i.runOnMainSync(()->{assertTrue(((Switch)toggle(activity.getWindow().getDecorView(),"Skip all-day dates")).isChecked());assertTrue(((Switch)toggle(activity.getWindow().getDecorView(),"Earlier for meetings")).isChecked());});assertEquals(prompted+1,requests.get());assertEquals(0,applied.get());
        }finally{if(activity!=null&&!activity.isDestroyed())close();CalendarRulesActivity.permissions=oldPermissions;CalendarSettings.factory=oldPrefs;CalendarAccess.factory=oldAccess;CalendarSync.port=oldApply;assertTrue(c.deleteSharedPreferences(name));assertEquals(before,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}
    }
    @Test public void calendarChoicesSaveAndReopenWithoutProviderOrAlarmEffects()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());String name="calendar-ui-"+UUID.randomUUID();SharedPreferences privatePrefs=c.getSharedPreferences(name,0);java.util.function.Function<Context,SharedPreferences> oldPrefs=CalendarSettings.factory;CalendarAccess.Factory oldAccess=CalendarAccess.factory;CalendarSync.Port oldApply=CalendarSync.port;AtomicInteger applied=new AtomicInteger();
        try{
            CalendarSettings.factory=context->privatePrefs;CalendarAccess.factory=context->new CalendarAccess.Port(){public boolean allowed(){return true;}public List<CalendarAccess.Source> sources(CancellationSignal signal){assertNotEquals(Looper.getMainLooper(),Looper.myLooper());return List.of(new CalendarAccess.Source(7,"Private calendar"));}public CalendarPolicy.Snapshot snapshot(CalendarPolicy.Rules rules,long now,ZoneId zone,CancellationSignal cancel){throw new AssertionError("Fixture never queries real events");}};
            CalendarSync.port=context->{assertNotEquals(Looper.getMainLooper(),Looper.myLooper());CalendarPolicy.Rules saved=CalendarSettings.load(context);assertTrue(saved.enabled);assertEquals(Set.of(7L),saved.holidays);assertEquals(Set.of(7L),saved.meetings);applied.incrementAndGet();};
            launch();capture("initial");click("Use calendar rules");click("Skip all-day dates");click("Earlier for meetings");assertTrue(privatePrefs.getAll().isEmpty());capture("draft");click("Save calendar rules");await(()->shown("Calendar rules saved."));assertEquals(1,applied.get());capture("saved");close();launch();assertTrue(CalendarSettings.load(c).enabled);assertEquals(Set.of(7L),CalendarSettings.load(c).meetings);capture("reopened");
        }finally{if(activity!=null&&!activity.isDestroyed())close();CalendarSettings.factory=oldPrefs;CalendarAccess.factory=oldAccess;CalendarSync.port=oldApply;assertTrue(c.deleteSharedPreferences(name));assertEquals(before,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}
    }
}
